import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

// 数据目录路径
const DATA_DIR = path.resolve(__dirname, '../../data');

// 内存中的数据缓存
let componentsData = null;
let indexData = null;
let categoriesData = {};

/**
 * 初始化JSON数据加载器
 */
export async function initializeJsonData() {
  try {
    console.error('[JSON Data Loader] 初始化组件JSON数据...');
    
    // 加载索引数据
    const indexPath = path.join(DATA_DIR, 'index.json');
    if (fs.existsSync(indexPath)) {
      indexData = JSON.parse(fs.readFileSync(indexPath, 'utf8'));
      console.error(`[JSON Data Loader] 索引数据已加载: ${indexData.metadata.totalComponents} 个组件`);
    } else {
      throw new Error(`索引文件不存在: ${indexPath}`);
    }
    
    // 加载完整组件数据
    const componentsPath = path.join(DATA_DIR, 'components.json');
    if (fs.existsSync(componentsPath)) {
      componentsData = JSON.parse(fs.readFileSync(componentsPath, 'utf8'));
      console.error('[JSON Data Loader] 完整组件数据已加载');
    } else {
      console.error('[JSON Data Loader] 警告: 完整组件数据文件不存在，将按需加载分类数据');
    }
    
    // 预加载所有分类数据
    const categories = ['animations', 'backgrounds', 'components', 'textanimations'];
    for (const category of categories) {
      const categoryPath = path.join(DATA_DIR, `${category}.json`);
      if (fs.existsSync(categoryPath)) {
        categoriesData[category] = JSON.parse(fs.readFileSync(categoryPath, 'utf8'));
        console.error(`[JSON Data Loader] ${category} 分类数据已加载`);
      }
    }
    
    console.error('[JSON Data Loader] JSON数据加载完成!');
    return true;
  } catch (error) {
    console.error('[JSON Data Loader] 加载JSON数据失败:', error);
    throw error;
  }
}

/**
 * 获取索引数据
 */
export function getIndexData() {
  if (!indexData) {
    throw new Error('索引数据未初始化，请先调用 initializeJsonData()');
  }
  return indexData;
}

/**
 * 获取所有组件数据
 */
export function getAllComponentsData() {
  if (componentsData) {
    return componentsData;
  }
  
  // 如果没有完整数据，合并分类数据
  const mergedData = {};
  Object.entries(categoriesData).forEach(([category, data]) => {
    mergedData[category] = data;
  });
  
  return mergedData;
}

/**
 * 获取特定分类的组件数据
 */
export function getCategoryData(category) {
  const normalizedCategory = category.toLowerCase();
  
  if (categoriesData[normalizedCategory]) {
    return categoriesData[normalizedCategory];
  }
  
  // 尝试从完整数据中获取
  if (componentsData && componentsData[normalizedCategory]) {
    return componentsData[normalizedCategory];
  }
  
  throw new Error(`分类 "${category}" 的数据不存在`);
}

/**
 * 获取特定组件的数据
 */
export function getComponentData(componentName, category = null, techStack = 'js-css') {
  const normalizedComponentName = componentName.toLowerCase().replace(/\s+/g, '');
  
  // 如果指定了分类，直接在该分类中查找
  if (category) {
    const categoryData = getCategoryData(category);
    const component = categoryData[normalizedComponentName];
    
    if (component && component[techStack]) {
      return component[techStack];
    }
  }
  
  // 在所有分类中搜索
  const allData = getAllComponentsData();
  for (const [cat, catData] of Object.entries(allData)) {
    if (catData[normalizedComponentName] && catData[normalizedComponentName][techStack]) {
      return catData[normalizedComponentName][techStack];
    }
  }
  
  throw new Error(`组件 "${componentName}" (${techStack}) 未找到`);
}

/**
 * 搜索组件
 */
export function searchComponents(query = '', category = null, techStack = null, limit = 10) {
  const results = [];
  const searchQuery = query.toLowerCase();
  const allData = getAllComponentsData();
  
  // 遍历所有分类和组件
  Object.entries(allData).forEach(([cat, catData]) => {
    // 如果指定了分类过滤器，跳过不匹配的分类
    if (category && cat !== category.toLowerCase()) {
      return;
    }
    
    Object.entries(catData).forEach(([componentName, techStackVariants]) => {
      // 检查组件名是否匹配搜索查询
      const displayName = Object.values(techStackVariants)[0]?.name || componentName;
      if (!query || 
          componentName.toLowerCase().includes(searchQuery) ||
          displayName.toLowerCase().includes(searchQuery) ||
          cat.includes(searchQuery)) {
        
        // 获取技术栈变体
        const availableStacks = Object.keys(techStackVariants);
        const targetStack = techStack && availableStacks.includes(techStack) ? techStack : availableStacks[0];
        
        if (techStackVariants[targetStack]) {
          results.push({
            name: componentName,
            displayName: displayName,
            category: cat,
            techStack: targetStack,
            availableStacks: availableStacks,
            data: techStackVariants[targetStack],
            metadata: techStackVariants[targetStack].metadata
          });
        }
      }
    });
  });
  
  // 限制结果数量
  return results.slice(0, limit);
}

/**
 * 获取所有分类列表
 */
export function getCategories(detailed = false) {
  const index = getIndexData();
  
  if (detailed) {
    return index.categories;
  }
  
  return Object.keys(index.categories);
}

/**
 * 获取组件统计信息
 */
export function getComponentStats() {
  const index = getIndexData();
  return {
    totalCategories: index.metadata.totalCategories,
    totalComponents: index.metadata.totalComponents,
    totalTechStacks: index.metadata.totalTechStacks,
    categories: index.categories,
    techStacks: index.techStacks,
    generatedAt: index.metadata.generatedAt,
    version: index.metadata.version
  };
}

/**
 * 获取组件列表（用于预览）
 */
export function getComponentsList(category = null) {
  const index = getIndexData();
  
  if (category) {
    const normalizedCategory = category.toLowerCase();
    const categoryInfo = index.categories[normalizedCategory];
    if (!categoryInfo) {
      throw new Error(`分类 "${category}" 不存在`);
    }
    return categoryInfo.components.map(name => ({
      name: name,
      displayName: name.replace(/([A-Z])/g, ' $1').trim(),
      category: normalizedCategory
    }));
  }
  
  return index.components;
}

/**
 * 验证数据完整性
 */
export function validateData() {
  try {
    const index = getIndexData();
    const stats = getComponentStats();
    
    console.error('[JSON Data Loader] 数据验证:');
    console.error(`  - 分类数量: ${stats.totalCategories}`);
    console.error(`  - 组件总数: ${stats.totalComponents}`);
    console.error(`  - 技术栈数量: ${stats.totalTechStacks}`);
    console.error(`  - 数据生成时间: ${stats.generatedAt}`);
    
    return true;
  } catch (error) {
    console.error('[JSON Data Loader] 数据验证失败:', error);
    return false;
  }
}

// 导出数据状态检查函数
export function isDataLoaded() {
  return indexData !== null && Object.keys(categoriesData).length > 0;
}